    std::vector<std::uint8_t> island_plunder_class_source()
    {
        std::vector<std::uint8_t> bytes;
        bytes.reserve(island_plunder_class_source_hex.size()/2);
        const auto nibble = [](const char c) -> std::uint8_t
        {
            if (c >= '0' && c <= '9') return static_cast<std::uint8_t>(c-'0');
            if (c >= 'a' && c <= 'f') return static_cast<std::uint8_t>(c-'a'+10);
            throw std::runtime_error("corrupt Island class fixture hex");
        };
        for(std::size_t i=0; i<island_plunder_class_source_hex.size(); i+=2)
            bytes.push_back(static_cast<std::uint8_t>(16*nibble(island_plunder_class_source_hex[i])+nibble(island_plunder_class_source_hex[i+1])));
        return bytes;
    }

    void island_plunder_class_translation_checks()
    {
        namespace abi = gsc::island_plunder_class_native_abi;
        const auto source = island_plunder_class_source();
        Check(source.size() == abi::source_length && abi::fingerprint(source) == abi::source_fingerprint,
            "pinned Island class fixture differs from installed module");
        const auto reject = [](std::string_view name, std::vector<std::uint8_t> bytes)
        {
            const auto before = bytes;
            Check(!abi::translate_private_compiler_copy(name,bytes) && bytes == before,
                "Plunder class ABI accepted or changed unknown ScriptFile");
        };
        reject("scripts/mp/class.gsc",source);
        reject("1877",source);
        reject(abi::source_module,{});
        auto shorter=source;shorter.pop_back();reject(abi::source_module,shorter);
        auto longer=source;longer.push_back(0);reject(abi::source_module,longer);
        for(std::size_t at : {std::size_t(0),source.size()-1,std::size_t(6130),std::size_t(6131),
                std::size_t(6307),std::size_t(6308),std::size_t(6776),std::size_t(6777),
                std::size_t(6851),std::size_t(6852)})
        {
            auto changed=source;changed[at]^=1;reject(abi::source_module,changed);
        }
        auto patched=source;
        Check(abi::translate_private_compiler_copy(abi::source_module,patched),
            "Plunder class ABI rejected the installed Source code");
        Check(abi::fingerprint(patched)==abi::replay_fingerprint && patched[6131]==5 && patched[6308]==5,
            "Plunder class ABI did not use Replay's 5 attachment DDL slots");
        for(std::size_t i=0;i<source.size();++i)
            Check(patched[i]==source[i] || i==6131 || i==6308,
                "Plunder class ABI changed an unrelated Source instruction");
        Check(patched[6777]==10 && patched[6852]==10,
            "Plunder class ABI changed original 10-field classstruct cleanup");
        reject(abi::source_module,patched);
        auto after_bad=source;
        Check(!abi::translate_exact_profile(abi::source_module,after_bad,abi::source_fingerprint,
            abi::replay_fingerprint^1) && after_bad==source,
            "Plunder class ABI failed to roll back mismatched output hash");
    }
